#!/usr/bin/env node

import { hideBin } from "yargs/helpers";
import yargs from "yargs/yargs";
import { resolve } from "path";
import fsExtra from "fs-extra";
import { fileURLToPath } from "url";
import { dirname } from "path";
import { readFileSync, writeFileSync } from "fs";

const args = yargs(hideBin(process.argv))
  .usage("Usage: $0 <project-name>")
  .demandCommand(1, "Please specify the project name").argv;

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const uxpVersion = "8.0";
const projectName = args._[0];
const templatePath = resolve(__dirname, "../templates/basic");
const destinationPath = resolve(process.cwd(), projectName);

fsExtra.copySync(templatePath, destinationPath);

console.log("\x1b[32m%s\x1b[0m", `Created UXP-SWC app in ${projectName}`);
console.log(
  `Please note that the UXP version supporting the components is \x1b[32m${uxpVersion}\x1b[0m`
);

// Read the package.json file
const packageJsonPath = resolve(destinationPath, "package.json");
const packageJson = JSON.parse(readFileSync(packageJsonPath, "utf8"));

// Update the "name" field
packageJson.name = projectName;

// Write the modified package.json back to the file
writeFileSync(packageJsonPath, JSON.stringify(packageJson, null, 2));
